    /// <summary>
    /// Parses the data containing an ID3v1 tag and returns a #GstTagList from the
    /// parsed data.
    /// </summary>
    /// <param name="data">
    /// 128 bytes of data containing the ID3v1 tag
    /// The C declaration sizes this buffer at 128 elements; pass exactly 128.
    /// </param>
    /// <returns>A new tag list or NULL if the data was not an ID3v1 tag.</returns>
    /// <exception cref="ArgumentException">
    /// <paramref name="data"/> does not have exactly 128 elements.
    /// </exception>
    public static Gst.TagList? TagListNewFromId3v1(System.ReadOnlySpan<byte> data)
    {
        if (data.Length != 128)
        {
            throw new ArgumentException(
                "data must have exactly 128 elements.",
                nameof(data));
        }
        fixed (byte* dataPointer = data)
        {
            nint nativeResult = GstTagListNewFromId3v1(dataPointer);
            return Gst.TagList.FromNative(nativeResult, Gst.Interop.Transfer.Full);
        }
    }

    /// <summary>
    /// Formats the tags in taglist on exif format. The resulting buffer contains
    /// the tags IFD and is followed by the data pointed by the tag entries.
    /// </summary>
    /// <param name="taglist">The taglist</param>
    /// <param name="byteOrder">byte order used in writing (G_LITTLE_ENDIAN or G_BIG_ENDIAN)</param>
    /// <param name="baseOffset">Offset from the tiff header first byte</param>
    /// <returns>A GstBuffer containing the tag entries followed by the tag data</returns>
    public static Gst.Buffer? TagListToExifBuffer(Gst.TagList taglist, int byteOrder, uint baseOffset)
    {
        ArgumentNullException.ThrowIfNull(taglist);
        nint nativeResult = GstTagListToExifBuffer(taglist.Handle, byteOrder, baseOffset);
        System.GC.KeepAlive(taglist);
        return Gst.Buffer.FromNative(nativeResult, Gst.Interop.Transfer.Full);
    }

