    /// <summary>Creates a new vorbiscomment buffer from a tag list.</summary>
    /// <param name="list">tag list to convert</param>
    /// <param name="idData">identification data at start of stream</param>
    /// <param name="vendorString">string that describes the vendor string or NULL</param>
    /// <returns>
    /// A new #GstBuffer containing a vorbiscomment buffer with all tags
    ///          that could be converted from the given tag list.
    /// </returns>
    public static Gst.Buffer TagListToVorbiscommentBuffer(Gst.TagList list, System.ReadOnlySpan<byte> idData, string? vendorString)
    {
        ArgumentNullException.ThrowIfNull(list);
        System.Span<byte> vendorStringBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope vendorStringScope = Gst.Interop.GMarshal.StackUtf8(vendorString, vendorStringBuffer);
        fixed (byte* idDataPointer = idData)
        {
            nint nativeResult = GstTagListToVorbiscommentBuffer(list.Handle, idDataPointer, (uint)idData.Length, vendorStringScope.Pointer);
            System.GC.KeepAlive(list);
            return Gst.Buffer.FromNative(nativeResult, Gst.Interop.Transfer.Full)
                ?? throw new InvalidOperationException("gst_tag_list_to_vorbiscomment_buffer returned no value.");
        }
    }

    /// <summary>
    /// Formats a taglist as a xmp packet using only the selected
    /// schemas. An empty list (%NULL) means that all schemas should
    /// be used
    /// </summary>
    /// <param name="list">tags</param>
    /// <param name="readOnly">does the container forbid inplace editing</param>
    /// <param name="schemas">    %NULL terminated array of schemas to be used on serialization</param>
    /// <returns>new buffer or %NULL, unref the buffer when done</returns>
    public static Gst.Buffer? TagListToXmpBuffer(Gst.TagList list, bool readOnly, string[]? schemas)
    {
        ArgumentNullException.ThrowIfNull(list);
        using Gst.Interop.StrvScope schemasScope = Gst.Interop.GMarshal.AllocStrv(schemas);
        nint nativeResult = GstTagListToXmpBuffer(list.Handle, readOnly ? 1 : 0, schemasScope.Pointer);
        System.GC.KeepAlive(list);
        return Gst.Buffer.FromNative(nativeResult, Gst.Interop.Transfer.Full);
    }

    /// <summary>
    /// Convenience function to parse a GST_TAG_EXTENDED_COMMENT string and
    /// separate it into its components.
    /// </summary>
    /// <remarks>
    /// <para>
    /// If successful, @key, @lang and/or @value will be set to newly allocated
    /// strings that you need to free with g_free() when done. @key and @lang
    /// may also be set to NULL by this function if there is no key or no language
    /// code in the extended comment string.
    /// </para>
    /// </remarks>
    /// <param name="extComment">an extended comment string, see #GST_TAG_EXTENDED_COMMENT</param>
    /// <param name="key">    return location for the comment description key, or NULL</param>
    /// <param name="lang">    return location for the comment ISO-639 language code, or NULL</param>
    /// <param name="value">return location for the actual comment string, or NULL</param>
    /// <param name="failIfNoKey">whether to fail if strings are not in key=value form</param>
    /// <returns>TRUE if the string could be parsed, otherwise FALSE</returns>
    public static bool TagParseExtendedComment(string extComment, out string? key, out string? lang, out string? value, bool failIfNoKey)
    {
        ArgumentNullException.ThrowIfNull(extComment);
        System.Span<byte> extCommentBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope extCommentScope = Gst.Interop.GMarshal.StackUtf8(extComment, extCommentBuffer);
        nint keyNative = default;
        nint langNative = default;
        nint valueNative = default;
        int nativeResult = GstTagParseExtendedComment(extCommentScope.Pointer, &keyNative, &langNative, &valueNative, failIfNoKey ? 1 : 0);
        key = Gst.Interop.GMarshal.PtrToStringUtf8AndFree(keyNative);
        lang = Gst.Interop.GMarshal.PtrToStringUtf8AndFree(langNative);
        value = Gst.Interop.GMarshal.PtrToStringUtf8AndFree(valueNative);
        return nativeResult != 0;
    }

