    /// <summary>Looks up the ID3v2 tag for a GStreamer tag.</summary>
    /// <param name="gstTag">GStreamer tag to convert to vorbiscomment tag</param>
    /// <returns>The corresponding ID3v2 tag or NULL if none exists.</returns>
    public static string? TagToId3Tag(string gstTag)
    {
        ArgumentNullException.ThrowIfNull(gstTag);
        System.Span<byte> gstTagBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope gstTagScope = Gst.Interop.GMarshal.StackUtf8(gstTag, gstTagBuffer);
        nint nativeResult = GstTagToId3Tag(gstTagScope.Pointer);
        return Gst.Interop.GMarshal.PtrToStringUtf8(nativeResult);
    }

    /// <summary>
    /// Creates a new tag list that contains the information parsed out of a
    /// vorbiscomment packet.
    /// </summary>
    /// <param name="list">a #GstTagList</param>
    /// <param name="tag">a GStreamer tag identifier, such as #GST_TAG_ARTIST</param>
    /// <returns>
    /// A #GList of newly-allocated
    ///     key=value strings. Free with g_list_foreach (list, (GFunc) g_free, NULL)
    ///     plus g_list_free (list)
    /// </returns>
    public static System.Collections.Generic.IReadOnlyList<string> TagToVorbisComments(Gst.TagList list, string tag)
    {
        ArgumentNullException.ThrowIfNull(list);
        ArgumentNullException.ThrowIfNull(tag);
        System.Span<byte> tagBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope tagScope = Gst.Interop.GMarshal.StackUtf8(tag, tagBuffer);
        nint nativeResult = GstTagToVorbisComments(list.Handle, tagScope.Pointer);
        System.GC.KeepAlive(list);
        nint[] nativeItems = Gst.Interop.GListMarshal.CollectAndFreeSpine(nativeResult);
        System.Collections.Generic.List<string> result = new(nativeItems.Length);
        foreach (nint nativeItem in nativeItems)
        {
            if (nativeItem != 0 && Gst.Interop.GMarshal.PtrToStringUtf8AndFree(nativeItem) is { } adopted)
            {
                result.Add(adopted);
            }
        }

        return result;
    }

    /// <summary>Looks up the vorbiscomment tag for a GStreamer tag.</summary>
    /// <param name="gstTag">GStreamer tag to convert to vorbiscomment tag</param>
    /// <returns>The corresponding vorbiscomment tag or NULL if none exists.</returns>
    public static string? TagToVorbisTag(string gstTag)
    {
        ArgumentNullException.ThrowIfNull(gstTag);
        System.Span<byte> gstTagBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope gstTagScope = Gst.Interop.GMarshal.StackUtf8(gstTag, gstTagBuffer);
        nint nativeResult = GstTagToVorbisTag(gstTagScope.Pointer);
        return Gst.Interop.GMarshal.PtrToStringUtf8(nativeResult);
    }

