    /// <summary>
    /// Convenience function using gst_tag_from_vorbis_tag(), parsing
    /// a vorbis comment string into the right type and adding it to the
    /// given taglist @list.
    /// </summary>
    /// <remarks>
    /// <para>
    /// Unknown vorbiscomment tags will be added to the tag list in form
    /// of a #GST_TAG_EXTENDED_COMMENT.
    /// </para>
    /// </remarks>
    /// <param name="list">a #GstTagList</param>
    /// <param name="tag">a vorbiscomment tag string (key in key=value), must be valid UTF-8</param>
    /// <param name="value">a vorbiscomment value string (value in key=value), must be valid UTF-8</param>
    public static void VorbisTagAdd(Gst.TagList list, string tag, string value)
    {
        ArgumentNullException.ThrowIfNull(list);
        ArgumentNullException.ThrowIfNull(tag);
        System.Span<byte> tagBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope tagScope = Gst.Interop.GMarshal.StackUtf8(tag, tagBuffer);
        ArgumentNullException.ThrowIfNull(value);
        System.Span<byte> valueBuffer = stackalloc byte[Gst.Interop.GMarshal.StackBufferSize];
        using Gst.Interop.Utf8Scope valueScope = Gst.Interop.GMarshal.StackUtf8(value, valueBuffer);
        GstVorbisTagAdd(list.Handle, tagScope.Pointer, valueScope.Pointer);
        System.GC.KeepAlive(list);
    }

